ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'outputs/qa-wide-chat-20261013'
OUT.mkdir(parents=True,exist_ok=True)
manifest=json.loads((ROOT/'outputs/qa-global-500-fixed-20261012/cases.json').read_text(encoding='utf-8'))
TODAY=date(2026,10,13)

def profile(months, name='Искусственный профиль'):
    total=TODAY.year*12+TODAY.month-1-months
    year,index=divmod(total,12); month=index+1
    return {'role':'mom','stage':'child','birthDate':date(year,month,min(TODAY.day,calendar.monthrange(year,month)[1])).isoformat(),
            'childName':name,'week':20,'weekDate':TODAY.isoformat(),'feeding':'unknown','sleep':'','health':'','healthConfirmed':False,'topics':[]}

for p in manifest['accounts'].values():
    if p and p.get('stage')=='child' and p.get('birthDate'):
        born=date.fromisoformat(p['birthDate']); reference=date(2026,10,12)
        age=(reference.year-born.year)*12+reference.month-born.month-(reference.day<min(born.day,calendar.monthrange(reference.year,reference.month)[1]))
        p.update(profile(age,p.get('childName','Искусственный профиль')))
for months in (0,1,2,5,6,8,11,12,14,23,24,36,60,84):
    manifest['accounts']['new-'+str(months)]=profile(months)
manifest['accounts']['new-parent']=profile(5)
manifest['accounts']['new-unknown']=None
manifest['accounts']['new-pregnancy']={'role':'mom','stage':'pregnancy','birthDate':'','childName':'Ожидание','week':24,'weekDate':TODAY.isoformat(),'feeding':'unknown','sleep':'','health':'','healthConfirmed':False,'topics':[]}

