backup=ROOT/'private'/('qa-wide-chat-before-20261013-'+secrets.token_hex(5));backup.mkdir()
fingerprints={}
for name in ('accounts.sqlite3','operations.sqlite3','ai-budget.sqlite3'):
    source=ROOT/'private/local-runtime'/name
    with sqlite3.connect('file:'+source.as_posix()+'?mode=ro',uri=True) as db,sqlite3.connect(backup/name) as target:
        db.backup(target)
        tables=[r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]
        fingerprints[name]={table:hashlib.sha256(json.dumps(sorted(db.execute('SELECT * FROM "'+table+'"').fetchall(),key=repr),default=str).encode()).hexdigest() for table in tables}
    assert target is not None
shutil.copytree(ROOT/'app/backend/parent-app/prompts',backup/'prompts')
for name in ('index.py','prompt_policy.py','content_policy.py','chat_safety.py','parent_support.py'):
    shutil.copy2(ROOT/'app/backend/parent-app'/name,backup/name)
report={'backup':str(backup),'databaseFingerprints':fingerprints,'qa50Sha256':hashlib.sha256((ROOT/'app/scripts/live-qa-50.mjs').read_bytes()).hexdigest()}
(OUT/'preservation-before.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
print(json.dumps({'cases':600,'newCases':len(new),'categories':dict(Counter(c['category'] for c in manifest['cases'])),'backupCreated':True}))
